]}
print(call(req))  # same instant (10:00Z == 12:00+02) -> tie, smallest record_id R-1 accepted; 1 accepted, 1 dup

# offset crossing date boundary, earlier UTC wins despite later local date
req2 = {"command":"count","receipts":[
    {"record_id":"R-1","account_id":"A","delivery_id":"D-2","occurred_at":"2026-04-02T01:00:00+03:00","payload":"p1"},
    {"record_id":"R-2","account_id":"A","delivery_id":"D-2","occurred_at":"2026-04-01T23:00:00Z","payload":"p2"},
]}
print(call(req2))  # R-1 = 2026-04-01T22:00Z, earlier than R-2 23:00Z -> R-1 accepted, 1/1

# omitted protocol
print(call({"command":"count","receipts":[]}))
